        core::slice::from_raw_parts(frame as *const c_uchar, width_usize.wrapping_mul(width_usize))
    };
    // SAFETY: the output writes at most `width + 1` entries (optional leading
    // `-1` plus one run per scanned row), so callers must provide non-null
    // writable storage for that many `c_int`s. No other Rust reference aliases
